import { useRef, useState } from 'react';
import './App.css';

/** The largest receipt the upload accepts, in bytes (2 MB). */
export const MAX_BYTES = 2 * 1024 * 1024;
export const ACCEPTED_TYPES = ['image/png', 'image/jpeg'];
/** Time between two progress reports of the fake upload, in ms. */
export const PROGRESS_STEP_MS = 150;

export interface UploadOptions {
  onProgress: (percent: number) => void;
  signal: AbortSignal;
}

const failedOnce = new Set<string>();
let uploadsStarted = 0;

/**
 * Given: a fake receipt upload. It reports progress four times, 25% at a time, PROGRESS_STEP_MS apart, then resolves
 * with the receipt's id. An upload of a name containing "flaky" fails instead of reporting 75%, the first time an
 * upload of that name gets that far in this page; later ones succeed. Aborting the signal stops the reports and
 * rejects with an AbortError.
 */
export function uploadReceipt(file: File, { onProgress, signal }: UploadOptions): Promise<{ id: string }> {
  return new Promise((resolve, reject) => {
    uploadsStarted += 1;
    const id = `receipt-${uploadsStarted}`;
    let percent = 0;
    let timer = 0;
    const abort = () => {
      window.clearTimeout(timer);
      reject(new DOMException('The upload was cancelled.', 'AbortError'));
    };
    if (signal.aborted) {
      abort();
      return;
    }
    signal.addEventListener('abort', abort, { once: true });
    const tick = () => {
      percent += 25;
      if (percent === 75 && file.name.includes('flaky') && !failedOnce.has(file.name)) {
        failedOnce.add(file.name);
        signal.removeEventListener('abort', abort);
        reject(new Error('The server rejected the upload.'));
        return;
      }
      onProgress(percent);
      if (percent < 100) {
        timer = window.setTimeout(tick, PROGRESS_STEP_MS);
        return;
      }
      signal.removeEventListener('abort', abort);
      resolve({ id });
    };
    timer = window.setTimeout(tick, PROGRESS_STEP_MS);
  });
}

/**
 * Given: counts preview URLs, so the checks can read them. It wraps URL.createObjectURL and URL.revokeObjectURL and
 * writes the number of open URLs to document.body's data-preview-urls attribute, and the number ever created to
 * data-preview-urls-created. Both stay after App unmounts.
 */
const openPreviewUrls = new Set<string>();
let createdPreviewUrls = 0;
const createUrl = URL.createObjectURL.bind(URL);
const revokeUrl = URL.revokeObjectURL.bind(URL);
const showOpenPreviewUrls = () => {
  document.body.dataset.previewUrls = String(openPreviewUrls.size);
  document.body.dataset.previewUrlsCreated = String(createdPreviewUrls);
};
URL.createObjectURL = (object: Blob | MediaSource) => {
  const url = createUrl(object);
  createdPreviewUrls += 1;
  openPreviewUrls.add(url);
  showOpenPreviewUrls();
  return url;
};
URL.revokeObjectURL = (url: string) => {
  openPreviewUrls.delete(url);
  revokeUrl(url);
  showOpenPreviewUrls();
};
showOpenPreviewUrls();

// TODO Task 1: make `.dropzone` a drop target. From the first dragenter of files over it, including over its
//              text, give it data-active="true"; remove the attribute when the drag leaves it or files are dropped
//              anywhere. Until the drop, dataTransfer.files is empty and dataTransfer.types includes "Files". Drags
//              that carry no files change nothing. Cancel dragover and drop of files on it and, with a listener on
//              window that leaves text drags alone, anywhere else on the page; only `.dropzone` adds files. Give
//              `.picker` an accept list for PNG and JPEG and the multiple attribute; a choice behaves like a drop.
//              Accept only files whose type is in ACCEPTED_TYPES and whose size is at most MAX_BYTES, checking the
//              type first, and list each other file of the latest drop or choice in `.rejections`, one li each in
//              the order received: `notes.pdf is not a PNG or JPEG image.` or `scan.jpg is larger than 2 MB.`
// TODO Task 2: upload each accepted file at once with uploadReceipt, side by side, in a new `.upload` row after
//              the others: `.upload-name`, a `.progress` bar (role="progressbar", aria-valuenow the percent, an
//              aria-label with the file name, a `.progress-fill` whose width is the percent) and `.upload-status`
//              reading `Uploading 0%`, `Uploading 25%`, `Uploaded`, `Upload failed` or `Cancelled`, with its buttons
//              in `.upload-actions`. `.cancel-upload`, only while uploading, stops it; `.retry`, for a failed or
//              cancelled upload, starts again from 0%; `.remove` stops it and drops the row. Cancel and Remove
//              leave no timer running. After each click, move focus within the row: Cancel to Retry, Retry to
//              Cancel; Remove to the next row's Remove, the previous one's, or `.choose`. Two files with the same
//              name are two rows. Stop every running upload on unmount.
// TODO Task 3: show each receipt in its row's `.thumb` image through an object URL. Create the URL once per file,
//              not on every render or retry, and revoke it when the row is removed and when App unmounts.

export default function App() {
  const [files, setFiles] = useState<File[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  const addFiles = (list: FileList) => {
    setFiles((current) => [...current, ...Array.from(list)]);
  };

  return (
    <main className="page">
      <section className="card">
        <header className="card-header">
          <h1 className="title">Receipts</h1>
          <p className="subtitle">Expense report · Spring offsite</p>
        </header>

        <div className="dropzone" onDrop={(event) => addFiles(event.dataTransfer.files)}>
          <p className="dropzone-hint">Drop receipts here</p>
          <p className="dropzone-note">PNG or JPEG, up to 2 MB each</p>
          <button type="button" className="choose" onClick={() => inputRef.current?.click()}>
            Choose files
          </button>
          <input
            ref={inputRef}
            className="picker"
            type="file"
            hidden
            onChange={(event) => {
              if (event.target.files) addFiles(event.target.files);
            }}
          />
        </div>

        <ul className="rejections" aria-live="polite" />

        <ul className="uploads">
          {files.map((file) => (
            <li className="upload" key={file.name}>
              <img className="thumb" src={URL.createObjectURL(file)} alt="" />
              <div className="upload-body">
                <span className="upload-name">{file.name}</span>
                <span className="upload-status">Waiting</span>
              </div>
            </li>
          ))}
        </ul>
      </section>
    </main>
  );
}

files.src/App.css:
:root {
  color-scheme: dark;
}

html,
body {
  margin: 0;
  min-height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.page {
  box-sizing: border-box;
  min-height: 100vh;
  background: #020617;
  color: #e5e7eb;
  display: grid;
  grid-template-columns: minmax(0, 560px);
  justify-content: center;
  align-content: start;
  padding: 24px 16px;
}

.card {
  box-sizing: border-box;
  min-width: 0;
  display: grid;
  gap: 16px;
  padding: 18px;
  border: 1px solid #1f2937;
  border-radius: 16px;
  background: #0b1220;
}

.card-header {
  display: grid;
  gap: 4px;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.dropzone {
  display: grid;
  justify-items: center;
  gap: 6px;
  padding: 24px 16px;
  border: 2px dashed #334155;
  border-radius: 12px;
  text-align: center;
  transition: border-color 120ms ease, background-color 120ms ease;
}

.dropzone[data-active='true'] {
  border-color: #60a5fa;
  background: #0f1d33;
}

.dropzone-hint {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
}

.dropzone-note {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.choose,
.cancel-upload,
.retry,
.remove {
  font: inherit;
  font-size: 13px;
  padding: 6px 12px;
  border-radius: 8px;
  border: 1px solid #334155;
  background: #1e293b;
  color: #e5e7eb;
  cursor: pointer;
}

.choose {
  margin-top: 6px;
}

.choose:focus-visible,
.cancel-upload:focus-visible,
.retry:focus-visible,
.remove:focus-visible {
  outline: 2px solid #93c5fd;
  outline-offset: 2px;
}

.rejections {
  display: grid;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 13px;
  color: #fca5a5;
}

.rejections li {
  overflow-wrap: anywhere;
}

.uploads {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.upload {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  align-items: center;
  gap: 8px 12px;
  padding: 10px;
  border: 1px solid #1f2937;
  border-radius: 10px;
}

.thumb {
  width: 48px;
  height: 48px;
  object-fit: cover;
  border-radius: 6px;
  background: #1e293b;
}

.upload-body {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.upload-name {
  font-size: 14px;
  overflow-wrap: anywhere;
}

.progress {
  height: 6px;
  border-radius: 999px;
  background: #1e293b;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: #60a5fa;
  transition: width 100ms linear;
}

.upload-status {
  font-size: 12px;
  color: #9ca3af;
}

.upload-actions {
  grid-column: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
